import {renderLive} from './live-render.mjs';
import {terms,eligiblePlans as eligibleCatalogPlans,matchingRule,generationResults,focusResult,correspondingPlan,rankResults,modelResolutions,resolutionForModel,configurationChoices} from './comparison.mjs';
import {models,platforms,plans,rules,sources,REVIEWED,CATALOG_VERSION,availability} from './data.mjs';
import {simulate,project,convert,pricing,numeric} from './engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4m-4 6h4M17 9h4m-4 6h4"/>',folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9H3z"/><path d="M8 13h8m-8 3h5"/>',layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',book:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1zM12 5v15"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',down:'<path d="m6 9 6 6 6-6"/>',up:'<path d="m6 15 6-6 6 6"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',check:'<path d="m5 12 4 4 10-10"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M16 12h5v5h-5zM5 5V3h13v2"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 2M4 17l2 2a8 8 0 0 0 13-2"/>',plus:'<path d="M12 5v14M5 12h14"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',chart:'<path d="M4 20V4m0 16h16M8 15l4-4 4 2 4-7"/>',save:'<path d="M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.info}</svg>`;
const defaults={view:'generations',currency:'BRL',fx:null,fxDate:null,fxType:'pending',fxFetched:null,sort:'cost',period:'monthly',includeEstimated:false,catalogNotice:false,expanded:null,gen:{plan:'mag-premium-monthly',model:'seedance-25',duration:8,resolution:'720p',count:3},accounts:{},manual:[],saved:[],prj:{name:'Meu próximo filme',plan:'mag-premium-monthly',scenes:[{id:'first',name:'Cenas principais',quantity:8,duration:8,attempts:5,model:'seedance-25',resolution:'720p'}],reserveType:'percent',reserve:20,items:[{id:'edit',name:'Edição de vídeo',type:'fixed',value:0,hours:1}],method:'margin',percent:40,provision:0}};
let s=structuredClone(defaults);
try {
 const stored=JSON.parse(localStorage.getItem('framecost-v1')||'null');
 if(stored&&[1,2].includes(stored.version)){
   s={...s,...stored.state,view:'generations',expanded:null};
   s.gen={...defaults.gen,...s.gen};s.prj={...defaults.prj,...s.prj};
   const legacy=stored.version<2||stored.catalogVersion!==CATALOG_VERSION;
   if(legacy){
     s.period='monthly';s.includeEstimated=false;s.catalogNotice=true;
     const oldPlan=plans.find(p=>p.id===s.prj.plan);
     s.prj.plan=oldPlan?(correspondingPlan(plans,oldPlan.id,'monthly')?.id||defaults.prj.plan):defaults.prj.plan;
     s.gen.plan=defaults.gen.plan;
   }
   if(!['monthly','annual'].includes(s.period))s.period='monthly';
   if(!models.some(m=>m.id===s.gen.model))s.gen.model=defaults.gen.model;
 }
}catch{}

let fxLoading=false,storageWarning=false, toastTimer;
const allPlans=()=>[...plans,...s.manual.map(x=>x.plan)];const allRules=()=>[...rules,...s.manual.map(x=>x.rule)];const info=p=>platforms.find(x=>x.id===p.platform)||{name:p.platformLabel||'Manual',mark:'M',color:'#a6d1ef',source:p.source};
const badge=status=>`<span class="badge ${status==='verified'?'':status}">${status==='verified'?'● Verificado':status==='estimated'?'◐ Estimado':status==='manual'?'✎ Informado manualmente':'○ Pendente'}</span>`;
const sourceLink=(key,label)=>{const src=sources[key];return src?`<a href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(label||src.name)} ↗</a>`:'Valor informado manualmente'};
const fmt=(n,d=0)=>n==null?'—':new Intl.NumberFormat('pt-BR',{maximumFractionDigits:d}).format(n);
const native=(v,c)=>v==null?'A confirmar':new Intl.NumberFormat('pt-BR',{style:'currency',currency:c}).format(v);
const money=(v,c=s.currency)=>{const n=convert(v,c,s.currency,s.fx);return n==null?'Câmbio pendente':native(n,s.currency)};
const economicMoney=(result,currency)=>`${result.economicEstimated?'≈ ':''}${money(result.economic,currency)}`;
const sourceStatus=p=>p.validUntil&&p.validUntil<today()?'pending':p.status;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});
const safe=(fn)=>{try{return {value:fn(),error:null}}catch(e){return {value:null,error:e.message}}};
function persist(){try{localStorage.setItem('framecost-v1',JSON.stringify({version:2,catalogVersion:CATALOG_VERSION,state:s}))}catch{storageWarning=true}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function numberInput(bind,value,min=0,max=100000,step=1){return `<input type="number" id="${esc(bind)}" data-bind="${esc(bind)}" data-number min="${min}" max="${max}" step="${step}" value="${esc(value)}">`}
function select(bind,value,options){if(bind.endsWith('.resolution')&&!options.some(([id])=>id===value))options=[[value,value+' · sem tarifa neste plano'],...options];return `<select id="${esc(bind)}" data-bind="${esc(bind)}" aria-label="${esc(bind==='period'?'Periodicidade dos planos':bind==='sort'?'Ordenação dos resultados':bind.split('.').at(-1))}">${options.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select>`}
function account(p){return {...(s.accounts[p.id]||{}),date:today()}}
function configs(model,planId=s.gen.plan){
  const p=allPlans().find(p=>p.id===planId),local=modelResolutions(p,allRules(),model);
  return local.length?local:modelResolutions(null,allRules(),model);
}
function ruleFor(p,scene){
  const r=matchingRule(p,allRules(),scene);
  return r&&r.billing&&r.status!=='pending'&&(r.status!=='estimated'||s.includeEstimated)?r:null;
}
function eligiblePlans(){return eligibleCatalogPlans(allPlans(),{period:s.period,date:today(),accounts:s.accounts});}
function results(){
  try{return generationResults({plans:allPlans(),rules:allRules(),config:s.gen,period:s.period,includeEstimated:s.includeEstimated,accounts:s.accounts,date:today()});}
  catch(e){return [{p:allPlans().find(p=>p.id===s.gen.plan)||allPlans()[0],error:e.message}];}
}
function rankRows(rows){return rankResults(rows,{sort:s.sort,currency:s.currency,fx:s.fx});}
function planOptions(scope='selected'){
  return (scope==='all'?allPlans():eligiblePlans()).map(p=>{
    const t=terms(p);return [p.id,`${info(p).name} · ${p.name} · ${native(t.monthlyPrice,p.currency)}/mês${p.period==='annual'?' equivalente, anual':' cobrado mensalmente'}`];
  });
}
function selectedResult(rows){return focusResult(rows,s.gen.plan);}
function layout(body){const views=[['generations','film','Gerações'],['projects','folder','Projetos'],['plans','layers','Planos e plataformas'],['sources','book','Fontes e metodologia']];const current=views.find(v=>v[0]===s.view)||views[0];return `<aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="generations" aria-label="Framecost início"><span class="brand-mark">f</span><span class="brand-name">framecost</span><sup>BETA</sup></a><p class="nav-label">SEU ESTÚDIO, MAIS EFICIENTE</p><nav class="nav" aria-label="Navegação principal">${views.map(([id,ic,n])=>`<button class="${s.view===id?'active':''}" ${s.view===id?'aria-current="page"':''} data-action="nav" data-view="${id}" title="${n}">${icon(ic)}<span class="nav-text">${n}</span>${id==='projects'?'<span class="new">NOVO</span>':''}</button>`).join('')}</nav><div class="sidebar-foot"><div class="local"><span class="dot"></span> Seu workspace local</div><p>Seus cálculos ficam neste navegador.<br>Mais clareza. Melhores decisões.</p></div></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span><span>${current[2]}</span></div><div class="mobile-brand"><span class="brand-mark">f</span>framecost</div><div class="top-actions"><span class="verified-top"><span class="dot"></span>Fontes consultadas · 23 out 2026</span><div class="currency" role="group" aria-label="Moeda dos resultados">${['USD','BRL'].map(c=>`<button data-action="currency" data-currency="${c}" aria-pressed="${s.currency===c}" class="${s.currency===c?'active':''}">${c}</button>`).join('')}</div><button class="btn ghost" data-action="export" aria-label="Exportar resumo">${icon('download')} Exportar resumo</button></div></header><main id="main" class="content view">${body}<div class="fx-strip">${icon('refresh')} ${s.fx?`US$ 1 = R$ ${fmt(s.fx,4)} · ${s.fxType==='manual'?'Taxa manual':'Referência Frankfurter'} · ${esc(s.fxDate)}${s.fxFetched?' · consulta '+esc(s.fxFetched):''}`:'Conversão entre moedas pendente. Preços originais preservados.'}<button data-action="fx">Configurar câmbio</button><button data-action="refresh-fx" ${fxLoading?'disabled':''}>${fxLoading?'Consultando…':'Atualizar referência'}</button></div><footer class="foot"><span>© 2026 Framecost · Decisões melhores, quadro a quadro.</span><button data-action="nav" data-view="sources">Como calculamos ${icon('external')}</button></footer>${storageWarning?'<p class="error">O navegador não permitiu salvar os dados. Exporte seu resumo para preservar o trabalho.</p>':''}</main></div>`}
function pageHead(eyebrow,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action||`<span class="head-tag">${icon('spark')} Planeje antes de gerar</span>`}</div>`}
function generationView(){
  const rows=rankRows(results()),chosen=selectedResult(rows),m=models.find(x=>x.id===s.gen.model);
  const focused=allPlans().find(p=>p.id===s.gen.plan),pending=rows.find(r=>r.p.id===s.gen.plan&&r.pending);
  const error=rows.find(r=>r.error);
  const focusOptions=planOptions();
  if(!focusOptions.some(([id])=>id===s.gen.plan))focusOptions.unshift([s.gen.plan,'Plano anterior indisponível neste ciclo — selecione um plano']);
  return `${pageHead('CUSTOS AUDITADOS. CRITÉRIOS IGUAIS.','Cada cena tem um custo.<br>Compare a mesma configuração.','Plano, ciclo e resolução ficam explícitos. O resumo mantém o plano que você escolheu.')}
  ${s.catalogNotice?`<div class="audit-notice" role="status">Catálogo e cálculos revisados. Revise saldos e tarifas manuais salvos antes desta atualização.<button class="btn ghost" data-action="dismiss-audit">Entendi</button></div>`:''}
  <section class="card configure" aria-label="Configuração da geração">
    <div class="section-title"><h2><span class="step">01</span> Configure sua geração</h2><small>Auditoria 2 · fontes oficiais e limites por plataforma</small></div>
    <div class="model-grid" role="group" aria-label="Modelo de vídeo">${models.map(x=>`<button data-action="model" data-model="${x.id}" class="model ${s.gen.model===x.id?'selected':''}" aria-pressed="${s.gen.model===x.id}"><span class="family"><span class="model-mark">${x.short}</span> ${x.family}</span><span class="model-name">${x.name}</span></button>`).join('')}</div>
    <div class="settings"><div class="duration-field"><label class="field-title" for="gen.duration">Duração do conteúdo</label><div class="duration-pills">${durationOptions(focused).map(n=>`<button data-action="duration" data-duration="${n}" class="${Number(s.gen.duration)===n?'active':''}" aria-pressed="${Number(s.gen.duration)===n}">${n}s</button>`).join('')}</div><div class="duration-custom">${numberInput('gen.duration',s.gen.duration,.1,86400,.1)}<span>segundos · projetos acima de 60s também</span></div></div>
    <label class="select-label"><span class="field-title">Resolução de saída</span>${select('gen.resolution',s.gen.resolution,configs(s.gen.model).map(r=>[r,r]))}<span class="field-note">Alterar resolução mantém seu plano em foco.</span></label>
    <label class="select-label"><span class="field-title">Cobrança da assinatura</span>${select('period',s.period,[['monthly','Mensal · pagamento por mês'],['annual','Anual · pagamento do ano']])}<span class="field-note">O comparativo nunca mistura os dois ciclos.</span></label></div>
    <div class="config-foot"><p>${icon('info')}<span>Texto/imagem, sem vídeo de entrada. Limites e áudio constam em cada tarifa.<br>Segmentos só seguem a regra da plataforma. Cotações isoladas não viram tarifa por segundo.</span></p><button class="btn ghost" data-action="account" data-plan="${esc(s.gen.plan)}">${icon('wallet')} Informar meu saldo</button></div>
  </section>
  <section class="card focus-panel" aria-label="Plano em foco"><label>Plano do resumo — mantido ao trocar resolução${select('gen.plan',s.gen.plan,focusOptions)}</label><div>${focused?`<span class="focus-plan">${esc(info(focused).name)} · ${esc(focused.name)} · ${focused.period==='annual'?'anual':'mensal'}</span><strong>${native(terms(focused).monthlyPrice,focused.currency)}/mês${focused.period==='annual'?' equivalente':''}</strong><small>Cobrança integral: ${native(focused.price,focused.currency)}/${focused.period==='annual'?'ano':'mês'}. ${focused.region?'Preço regional '+focused.region+'. ':''}${focused.creditPeriod==='annual'?fmt(focused.credits)+' créditos anuais disponíveis':fmt(focused.credits)+' créditos liberados por mês'}.</small>`:'Escolha um plano.'}</div></section>
  ${configurationHint(focused,pending)}
  ${error?`<div class="error" role="alert">${esc(error.error)}</div>`:''}
  ${chosen&&(chosen.r.status==='estimated'||chosen.p.status==='manual')?`<div class="audit-notice">${badge(chosen.r.status==='estimated'?'estimated':'manual')} ${esc(chosen.r.note||'Tarifa informada manualmente.')}</div>`:''}
  <div class="metrics"><article class="card metric featured"><p class="metric-label">${icon('film')} Custo econômico · 1 execução</p><p class="metric-value">${chosen?economicMoney(chosen.one,chosen.p.currency):'A confirmar'}</p><p class="metric-sub">${chosen?`${esc(info(chosen.p).name)} · ${esc(chosen.p.name)} · ${chosen.one.generated}s gerados`:'Tarifa não confirmada neste plano e configuração.'}</p></article>
  <article class="card metric"><p class="metric-label">${icon('layers')} Custo econômico · 3 execuções</p><p class="metric-value">${chosen?economicMoney(chosen.three,chosen.p.currency):'A confirmar'}</p><p class="metric-sub">${chosen?fmt(chosen.three.required,2)+' créditos · mesmo plano e resolução':'Não combinamos tarifas de outras plataformas.'}</p></article>
  <article class="card metric"><p class="metric-label">${icon('wallet')} Pagamento adicional · 1 execução</p><p class="metric-value">${chosen?(chosen.one.payment==null?'A confirmar':money(chosen.one.payment,chosen.p.currency)):'A confirmar'}</p><p class="metric-sub">${chosen?account(chosen.p).owned?'Acesso já pago e saldo informado.':chosen.p.period==='annual'?'Inclui a contratação do ano inteiro.':'Inclui a mensalidade inteira da contratação.':'Saldo externo não consultado.'}</p></article></div>
  ${resolutionAudit(focused)}${comparison(rows)}${retrySection(chosen)}`;
}
function comparison(rows){
  const valid=rows.filter(r=>!r.pending&&!r.error),pending=rows.filter(r=>r.pending);
  return `<section aria-label="Comparação de plataformas"><div class="results-head"><div><h2>Comparativo · cobrança ${s.period==='annual'?'anual':'mensal'}</h2><p>${valid.length} tarifas calculáveis · preços do plano normalizados por mês; desembolso separado</p></div><div class="results-controls"><label class="toggle-label"><input type="checkbox" data-bind="includeEstimated" ${s.includeEstimated?'checked':''}> Mostrar tarifas aproximadas</label>${select('sort',s.sort,[['cost','Custo de 1 execução'],['payment','Desembolso de 1 execução'],['capacity','Capacidade disponível agora']])}<button class="icon-btn" data-action="manual" aria-label="Adicionar tarifa manual">${icon('plus')}</button></div></div>
    <div class="card comparison"><div class="comparison-head"><span>Plataforma / plano</span><span>1 execução</span><span>3 execuções</span><span>Créditos / 1x</span><span>Plano / mês equivalente</span><span>Pagamento extra / 1x</span><span></span></div>
    ${valid.length?valid.map(rowHTML).join(''):'<div class="empty"><strong>Sem tarifa auditada para esta configuração.</strong>As opções pendentes continuam listadas abaixo. Você pode informar uma tarifa da sua conta.</div>'}
    <div class="table-foot">${icon('info')}<span>Os selos comparam somente mesmo modelo, resolução, qualidade, áudio, duração gerada e ciclo. O resumo é o plano escolhido, mesmo que outro resultado custe menos. Valores com ≈ incluem estimativa para créditos além do saldo e não recebem selo de menor custo. No anual, o preço por mês é equivalente; o pagamento inicial inclui o ano.</span></div></div>
    ${pending.length?`<details class="pending-data"><summary>${pending.length} opções com tarifa ou compatibilidade pendente</summary>${pending.map(r=>`<div class="pending-item"><strong>${esc(info(r.p).name)} · ${esc(r.p.name)}</strong><span>${esc(r.reason)}</span>${sourceLink(r.r?.source||r.p.source,'Ver fonte')}</div>`).join('')}</details>`:''}</section>`;
}
function rowHTML(row){
  const {p,r,one:o,three:t}=row,inf=info(p),expanded=s.expanded===p.id,term=terms(p);
  const status=p.status==='manual'?'manual':r.status==='estimated'?'estimated':sourceStatus(p);
  const focused=s.gen.plan===p.id;
  const billing=r.billing.type==='second'?`${fmt(r.billing.rate,4)} cr./s · ${r.billing.min}–${r.billing.max}s por clipe`:r.billing.type==='block'?`${r.billing.rate} cr. por bloco de ${r.billing.block}s`:r.billing.options.map(q=>`${q.seconds}s = ${fmt(q.credits,2)} cr.`).join(' / ');
  return `<div class="result-row ${focused?'focused':row.best?'best':''}"><div class="platform-name"><span class="platform-logo" style="color:${inf.color}">${esc(inf.mark)}</span><div><strong>${esc(inf.name)}</strong><small>${esc(p.name)} · ${p.period==='annual'?'anual':'mensal'}</small>${focused?'<span class="tiny-tag">Plano do resumo</span>':''}${row.best?'<span class="tiny-tag">Menor custo equivalente · 1x</span>':''}${row.bestThree?'<span class="tiny-tag">Menor custo equivalente · 3x</span>':''}</div></div>
  <div><span class="result-number">${economicMoney(o,p.currency)}</span><span class="result-detail">${o.segments} clipe(s) · ${fmt(o.generated,1)}s · ${esc(r.resolution)}<br>${money(o.perSecond,p.currency)}/s gerado</span></div>
  <div><span class="result-number">${economicMoney(t,p.currency)}</span><span class="result-detail">${fmt(t.required,2)} créditos</span></div>
  <div><span class="result-number">${fmt(o.required,2)}</span><span class="result-detail">${fmt(o.capacity)} execuções no saldo atual<br>${esc(r.quality)} · ${esc(r.audio)}</span></div>
  <div><span class="result-number">${native(term.monthlyPrice,p.currency)}/mês</span><span class="result-detail">${p.period==='annual'?'equivalente · '+native(p.price,p.currency)+'/ano':'cobrado mensalmente'}<br>${fmt(p.credits)} cr. ${p.creditPeriod==='annual'?'anuais':'mensais'}</span></div>
  <div><span class="result-number">${o.payment==null?'A confirmar':money(o.payment,p.currency)}</span><span class="result-detail">${account(p).owned?'Acesso já pago':'Nova contratação'}</span>${badge(status)}</div>
  <button class="icon-btn" data-action="details" data-plan="${p.id}" aria-expanded="${expanded}" aria-label="Detalhes ${esc(inf.name)} ${esc(p.name)} ${p.period}">${icon(expanded?'up':'down')}</button></div>
  ${expanded?`<div class="row-details"><div class="details-grid"><div><strong>Consumo deste plano</strong><br>Saldo agora: ${fmt(o.available,2)} cr.<br>Após 1x: ${fmt(o.remaining,2)} cr.; após 3x: ${fmt(t.remaining,2)} cr.<br>Déficit para 3x: ${fmt(t.shortfall,2)} cr.<br>Valor de origem do crédito: ${fmt(o.unitRate,8)} ${p.currency}.<br>Consumo de 1x: ${o.percent==null?'—':fmt(o.percent,2)+'%'}; restam ${fmt(o.capacityAfter)} execuções.</div><div><strong>Regra auditada</strong><br>${esc(billing)}<br>${esc(r.quality)} · ${esc(r.audio)}<br>${esc(r.note||'Tarifa manual.')}<br>Validade: ${esc(p.expires)}.</div><div><strong>Cobrança e fonte</strong><br>Contrato: ${native(p.price,p.currency)}/${p.period==='annual'?'ano':'mês'}.<br>Extra para 3x: ${t.payment==null?'a confirmar':money(t.payment,p.currency)}.<br>${esc(t.paymentReason)}<br>${sourceLink(p.source,'Preço do plano')} · ${sourceLink(r.source,'Consumo')}<br>${r.limitsSource?sourceLink(r.limitsSource,'Limites de duração'):''}</div></div><p>${esc(p.limits)} ${o.economicEstimated?'O custo atribuído ao consumo além do saldo é estimado; consulte a condição de recarga.':''}</p><div class="inline"><button class="btn primary" data-action="focus-plan" data-plan="${p.id}">Usar este plano no resumo</button><button class="btn ghost" data-action="account" data-plan="${p.id}">Editar saldo</button>${p.status==='manual'?`<button class="btn danger" data-action="delete-manual" data-plan="${p.id}">Remover tarifa manual</button>`:''}</div></div>`:''}`;
}
function retrySection(chosen){const r=chosen?.retry;return `<div class="bottom-grid"><section class="card retry"><div class="section-title"><h2>E se eu precisar gerar <span style="color:var(--green)">${fmt(s.gen.count)} vezes</span>?</h2><div class="counter"><button data-action="retry-down" aria-label="Menos uma execução">−</button><label style="font-size:0">Execuções${numberInput('gen.count',s.gen.count,1,100000)}</label><button data-action="retry-up" aria-label="Mais uma execução">+</button></div></div>${chosen?`<p class="muted">Tentativas, variações e ajustes. Reserve espaço para explorar.<br>${esc(info(chosen.p).name)} · ${esc(chosen.p.name)} · planejamento, sem garantia de tentativas.</p><div class="retry-values"><div><small>Custo econômico total</small><strong style="color:var(--green)">${economicMoney(r,chosen.p.currency)}</strong></div><div><small>Créditos consumidos</small><strong>${fmt(r.required,2)} <span style="font-size:10px;color:var(--dim)">cr.</span></strong></div><div><small>Saldo restante</small><strong>${fmt(r.remaining,2)}</strong></div></div><div class="progress" role="progressbar" aria-label="Saldo consumido" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,r.percent??0)}"><i style="width:${Math.min(100,r.percent??0)}%"></i></div><div class="progress-label"><span>${r.percent==null?'Sem saldo':fmt(r.percent,2)+'% do saldo consumido'}${r.shortfall?' · faltam '+fmt(r.shortfall,2)+' cr.':''}</span><span>Extra: ${r.payment==null?'a confirmar':money(r.payment,chosen.p.currency)}</span></div><p class="muted">${money(r.perSecond,chosen.p.currency)}/s gerado · ${fmt(r.capacityAfter)} execuções ainda possíveis.<br>${r.economicEstimated?'≈ Custo estimado para créditos além do saldo; preço de compra sujeito à condição de recarga. ':''}${esc(r.paymentReason)}</p>`:'<p class="muted">Informe uma quantidade válida e uma configuração com tarifa para consultar o consumo. O campo de execuções continua disponível durante a edição.</p>'}</section><section class="card project-teaser"><div class="eyebrow">DO PRIMEIRO FRAME AO ORÇAMENTO</div><h2>Um filme inteiro em mente?</h2><p>Planeje cenas, reserve novas tentativas e transforme custos de produção em um preço que faz sentido.</p><button class="btn primary" data-action="use-project">Calcular meu projeto ${icon('arrow')}</button><div class="film-art" aria-hidden="true"><i></i><i></i><i></i></div></section></div>`}
function projectCalc(p){
  if(!p)throw new Error('Selecione um plano válido.');
  if(p.period!==s.period)throw new Error('O plano está em outro ciclo de cobrança. Selecione um plano '+(s.period==='annual'?'anual':'mensal')+'.');
  const ops=s.prj.items.map(x=>({...x,value:convert(Number(x.value),s.currency,p.currency,s.fx)}));
  if(ops.some((x,i)=>x.value==null&&Number(s.prj.items[i].value)!==0))throw new Error('Informe o câmbio para converter os custos operacionais.');
  ops.forEach(x=>{if(x.value==null)x.value=0;});
  return project(p,s.prj.scenes,scene=>ruleFor(p,scene),{reserveType:s.prj.reserveType,reserve:s.prj.reserve,items:ops,pricing:{method:s.prj.method,percent:s.prj.percent,provision:s.prj.provision},account:account(p)});
}
function projectsView(){const p=allPlans().find(x=>x.id===s.prj.plan)||{id:s.prj.plan,name:'Plano indisponível',platform:'manual',price:null,credits:null,currency:s.currency,period:s.period},c=safe(()=>projectCalc(p)),r=c.value;return `${pageHead('SEU TRABALHO TEM VALOR.','Do conceito ao orçamento.','Planeje a produção, conheça seus custos e encontre o preço do seu próximo projeto.',`<button class="btn ghost" data-action="saved">${icon('folder')} Projetos salvos (${s.saved.length})</button>`)}<div class="project-layout"><div class="project-form"><section class="card"><div class="section-title"><h2><span class="step">01</span> O que vamos produzir?</h2><button class="icon-btn" data-action="save-project" aria-label="Salvar projeto">${icon('save')}</button></div><div class="form-grid"><label>Ciclo de cobrança${select('period',s.period,[['monthly','Mensal'],['annual','Anual']])}</label><label>Nome do projeto<input id="prj.name" data-bind="prj.name" value="${esc(s.prj.name)}" maxlength="120"></label><label>Plataforma e plano${select('prj.plan',p.id,planOptions())}</label></div><p class="muted">Custos operacionais e orçamento em ${s.currency}. O preço original do plano é ${native(p.price,p.currency)}. Cada grupo de cenas pode ter modelo e duração próprios.</p>${s.prj.scenes.map((scene,i)=>sceneHTML(scene,i)).join('')}<button class="btn ghost" data-action="add-scene">${icon('plus')} Adicionar grupo de cenas</button></section><section class="card"><div class="section-title"><h2><span class="step">02</span> Espaço para novas tentativas</h2></div><div class="form-grid"><label>Método de reserva${select('prj.reserveType',s.prj.reserveType,[['percent','Percentual adicional de créditos'],['extra','Execuções completas adicionais']])}</label><label>${s.prj.reserveType==='percent'?'Reserva de consumo (%)':'Execuções extras no projeto'}${numberInput('prj.reserve',s.prj.reserve,0,s.prj.reserveType==='percent'?1000:100000,s.prj.reserveType==='percent'?.1:1)}</label></div><p class="muted">${s.prj.reserveType==='percent'?'Reserva financeira de consumo, separada das tentativas-base. Não representa uma promessa de clipes fracionados.':'Execuções extras distribuídas alternadamente entre os grupos, uma por grupo a cada rodada. Cada extra gera todos os segmentos de uma cena.'}</p></section><section class="card"><div class="section-title"><h2><span class="step">03</span> O trabalho além da IA</h2></div>${s.prj.items.map((x,i)=>costHTML(x,i)).join('')}<button class="btn ghost" data-action="add-cost" style="margin-top:17px">${icon('plus')} Adicionar custo operacional</button></section><section class="card"><div class="section-title"><h2><span class="step">04</span> Seu preço, com clareza</h2></div><div class="form-grid"><label>Método de precificação${select('prj.method',s.prj.method,[['margin','Margem sobre o preço de venda'],['markup','Markup sobre o custo']])}</label><label>${s.prj.method==='margin'?'Margem desejada (%)':'Markup desejado (%)'}${numberInput('prj.percent',s.prj.percent,0,s.prj.method==='margin'?99.99:10000,.1)}</label><label>Provisão sobre a venda (%)${numberInput('prj.provision',s.prj.provision,0,99.99,.1)}</label><div class="muted" style="align-self:end">Provisão opcional para despesas proporcionais. Nenhuma alíquota tributária é presumida.</div></div></section></div><aside class="card quote" aria-label="Resumo financeiro do projeto"><div class="eyebrow">SEU PRÓXIMO ORÇAMENTO</div><h2>${esc(s.prj.name||'Projeto sem nome')}</h2>${c.error?`<div class="error" role="alert">${esc(c.error)}<br>Selecione outro plano ou cadastre a tarifa compatível.</div>`:`<span class="field-title">Preço de venda sugerido · ${s.currency}</span><div class="quote-total">${money(r.sale,p.currency)}</div><p>${fmt(r.sceneCount)} cenas · ${fmt(r.desired,1)}s de conteúdo pretendido<br>${fmt(r.executions)} execuções-base · ${fmt(r.segments)} clipes-base<br>${fmt(r.baseGenerated,1)}s gerados nas tentativas-base${r.extraSegments?' · '+fmt(r.extraSegments)+' clipes extras':''}</p><div class="breakdown"><div><span>IA · cenário-base</span><strong>${money(r.baseAI,p.currency)}</strong></div><div><span>Reserva de tentativas</span><strong>${money(r.reserveAI,p.currency)}</strong></div><div><span>Custos operacionais</span><strong>${money(r.operational,p.currency)}</strong></div><div class="total"><span>Custo total de produção</span><strong>${money(r.total,p.currency)}</strong></div><div><span>Provisão sobre a venda</span><strong>${money(r.fees,p.currency)}</strong></div><div><span>Lucro estimado</span><strong style="color:var(--green)">${money(r.profit,p.currency)}</strong></div><div><span>Margem efetiva</span><strong>${fmt(r.margin,2)}%</strong></div></div><div class="breakdown"><div><span>Créditos necessários</span><strong>${fmt(r.required,2)}</strong></div><div><span>Pagamento adicional de IA</span><strong>${r.payment==null?'A confirmar':money(r.payment,p.currency)}</strong></div><div><span>Outros pagamentos operacionais</span><strong>${money(r.operational,p.currency)}</strong></div></div><p>${r.economicEstimated?'O custo econômico inclui estimativa de créditos além do saldo disponível. ':''}${esc(r.paymentReason)} O pagamento adicional não é somado novamente ao custo econômico.</p><p>Reserva: ${fmt(r.reserveCredits,2)} cr. · saldo original restante: ${fmt(r.remaining,2)} cr. Os custos operacionais são tratados como pagamentos a realizar.</p><button class="btn primary" data-action="export-project">${icon('download')} Exportar orçamento</button><button class="btn ghost" data-action="save-project">${icon('save')} Salvar neste navegador</button>`}</aside></div>${projectComparison()}`}
function sceneHTML(x,i){const b=`prj.scenes.${i}`;return `<div class="scene"><div class="scene-top"><label style="font-size:0">Nome do grupo<input id="${b}.name" data-bind="${b}.name" value="${esc(x.name)}" maxlength="80"></label><button class="icon-btn" data-action="remove-scene" data-index="${i}" aria-label="Remover grupo ${i+1}">${icon('trash')}</button></div><div class="form-grid three"><label>Cenas${numberInput(b+'.quantity',x.quantity,1,10000)}</label><label>Segundos por cena${numberInput(b+'.duration',x.duration,.1,86400,.1)}</label><label>Execuções por cena${numberInput(b+'.attempts',x.attempts,1,10000)}</label><label>Modelo${select(b+'.model',x.model,models.map(m=>[m.id,m.name]))}</label><label>Resolução${select(b+'.resolution',x.resolution,configs(x.model,s.prj.plan).map(r=>[r,r]))}</label></div></div>`}
function costHTML(x,i){const b=`prj.items.${i}`;return `<div class="cost-item"><label>Descrição<input id="${b}.name" data-bind="${b}.name" value="${esc(x.name)}" maxlength="100"></label><label>Tipo${select(b+'.type',x.type,[['fixed','Fixo'],['scene','Por cena'],['hour','Por hora']])}</label><label>Valor · ${s.currency}${numberInput(b+'.value',x.value,0,1e8,.01)}</label>${x.type==='hour'?`<label>Horas${numberInput(b+'.hours',x.hours,0,100000,.1)}</label>`:'<span></span>'}<button class="icon-btn" data-action="remove-cost" data-index="${i}" aria-label="Remover custo ${esc(x.name)}">${icon('trash')}</button></div>`}
function projectComparison(){const rows=eligiblePlans().flatMap(p=>{const c=safe(()=>projectCalc(p));return c.value?[{p,r:c.value}]:[]}).sort((a,b)=>(convert(a.r.total,a.p.currency,s.currency,s.fx)??Infinity)-(convert(b.r.total,b.p.currency,s.currency,s.fx)??Infinity));return `<section style="margin-top:28px"><div class="results-head"><div><h2>O mesmo projeto, outras possibilidades.</h2><p>Mesmas cenas, tentativas, custos operacionais e precificação. Confira qualidade, áudio e duração gerada.</p></div></div><div class="card comparison"><div class="comparison-head project-comparison-head"><span>Plataforma / plano</span><span>IA / consumo</span><span>Duração gerada</span><span>Custo total</span><span>Preço sugerido</span><span>Pagamento extra IA</span></div>${rows.length?rows.map(({p,r})=>`<div class="result-row project-row"><div class="platform-name"><span class="platform-logo" style="color:${info(p).color}">${info(p).mark}</span><div><strong>${info(p).name}</strong><small>${esc(p.name)} · ${p.period==='annual'?'anual':'mensal'}</small>${badge(sourceStatus(p))}</div></div><div><span class="result-number">${r.economicEstimated?'≈ ':''}${money(r.ai,p.currency)}</span><span class="result-detail">${fmt(r.required,2)} cr.${r.economicEstimated?' · custo além do saldo estimado':''}</span></div><div><span class="result-number">${fmt(r.baseGenerated,1)}s</span><span class="result-detail">${r.details.map(d=>esc(d.rule.quality)+' · '+esc(d.rule.audio)).filter((v,i,a)=>a.indexOf(v)===i).join('<br>')}</span></div><div><span class="result-number">${money(r.total,p.currency)}</span><span class="result-detail">Operação: ${money(r.operational,p.currency)}</span></div><div><span class="result-number green">${money(r.sale,p.currency)}</span><span class="result-detail">Mesma margem aplicada</span></div><div><span class="result-number">${r.payment==null?'A confirmar':money(r.payment,p.currency)}</span><span class="result-detail">Plano: ${native(terms(p).monthlyPrice,p.currency)}/mês equivalente<br>Cobrança: ${native(p.price,p.currency)}/${p.period==='annual'?'ano':'mês'}<br>${sourceLink(p.source,'Fonte e contratação')}</span></div></div>`).join(''):'<div class="empty">Nenhuma alternativa tem tarifas para todas as cenas. Adicione regras manuais ou ajuste as cenas.</div>'}<div class="table-foot">${icon('info')}<span>Alternativas com duração efetiva, áudio ou qualidade diferentes não recebem selo de melhor custo. O total de contratação é independente do custo econômico. Fontes comerciais consultadas em 23/10/2026. Reserva percentual representa orçamento de consumo.</span></div></div></section>`}
function plansView(){
  return `${pageHead('MESMO CICLO, MESMA BASE.','Preço por mês. Cobrança explícita.','Escolha um ciclo para ver todos os planos na mesma base de comparação.')}<div class="card billing-panel"><label>Ciclo de cobrança${select('period',s.period,[['monthly','Mensal'],['annual','Anual']])}</label><p>O valor por mês de um plano anual é equivalente. A contratação exige o pagamento anual integral. Créditos anuais não são convertidos em saldo mensal disponível.</p></div><div class="source-cards">${platforms.map(pl=>`<section class="card source-card"><h2><span class="platform-logo" style="color:${pl.color}">${pl.mark}</span>${pl.name}</h2><p>${esc(pl.note)}</p>${plans.filter(p=>p.platform===pl.id&&p.period===s.period).map(p=>{const t=terms(p);return `<div class="plan-fact"><div><strong>${esc(p.name)}</strong> ${badge(sourceStatus(p))}<span style="display:block;margin-top:7px"><strong>${native(t.monthlyPrice,p.currency)}/mês${p.period==='annual'?' equivalente':''}</strong><br>Pagamento: ${native(p.price,p.currency)}/${p.period==='annual'?'ano':'mês'}<br>${fmt(p.credits)} créditos ${p.creditPeriod==='annual'?'anuais, liberados no período':'liberados por mês'}<br>${esc(p.expires)}${p.validUntil?'<br>Promoção até '+esc(p.validUntil):''}</span></div><button class="icon-btn" data-action="account" data-plan="${p.id}" aria-label="Saldo ${pl.name} ${p.name}">${icon('wallet')}</button></div>`;}).join('')}<p>${sourceLink(pl.source,'Fonte oficial')} · ${REVIEWED}</p></section>`).join('')}</div>`;
}
function sourcesView(){
  return `${pageHead('AUDITORIA DO CATÁLOGO · REVISÃO 2','Cada número precisa de uma origem.','Preços e ciclos conferidos nas páginas carregadas, com divergências de consumo explícitas.')}<div class="source-list">${Object.entries(sources).filter(([k])=>k!=='fx').map(([k,v])=>`<article class="card source-entry"><div>${sourceLink(k)}<small>Consulta: ${esc(v.date)}. ${esc(v.note||'Fonte oficial; não garante preço futuro.')}</small></div></article>`).join('')}</div><section class="card method"><h2>O que foi corrigido</h2><h3>Uma base de cobrança por comparação</h3><p>Mensal e anual ficam separados em todas as telas. Preços do plano aparecem por mês, com a palavra equivalente no anual. A cobrança integral continua visível. Magnific mensal e anual usam suas próprias quantidades de créditos, sem presumir que a alocação anual seja a mensal multiplicada por 12.</p><h3>Plano em foco fixo</h3><p>Mudar de 480p para 1080p mantém plataforma, plano e ciclo no resumo. Se a tarifa dessa resolução não estiver auditada, mostramos pendência. Não substituímos a plataforma silenciosamente. O quadro de resoluções compara exclusivamente o plano em foco.</p><h3>Duração e cobrança</h3><p>Tarifas por segundo usam limites específicos da plataforma. Uma cena de 31s em modelo de 4–30s é repartida como 27s + 4s, sem cobrar 34s. Cotações isoladas de 3s ou 5s não são interpretadas como blocos obrigatórios ou extrapoladas para outras durações. Tarifas por blocos e durações fixas só são usadas quando a regra foi informada explicitamente.</p><h3>Áudio, qualidade e dados pendentes</h3><p>Kling 3 na Magnific tem preço com e sem áudio; o catálogo atual calcula a tarifa sem áudio explicitamente. Tarifas aproximadas da Higgsfield ficam desligadas por padrão. Krea e SJinn não têm consumo por versão/configuração deduzido de contagens aproximadas. Limites não confirmados não são emprestados de outra plataforma.</p><h3>Custo econômico e pagamento</h3><p>O custo por crédito usa o preço atribuível ao período de liberação daquele saldo. Em anual com créditos mensais, usa preço anual/12 dividido pelos créditos mensais. Em saldo anual integral, usa o preço anual dividido pelos créditos anuais. O pagamento adicional contrata o ciclo inteiro ou pacotes conhecidos; saldo pago suficiente exige zero pagamento adicional. Recarga sem tarifa confirmada permanece a confirmar.</p><h3>Projeto e precificação</h3><p>As cenas usam as mesmas regras das gerações. Reserva aparece uma única vez. Markup: custo × (1 + percentual) / (1 − provisão). Margem: custo / (1 − margem − provisão). A provisão incide sobre a venda. Não aplicamos impostos ou taxas sem entrada do usuário.</p><h3>Saldo e câmbio</h3><p>O saldo é informado pelo usuário, nunca consultado na conta externa. Lotes vencidos são excluídos. Valores nativos ficam preservados; USD/BRL usa taxa manual ou referência datada. Projetos e dados manuais são armazenados neste navegador.</p></section>`;
}
function render(preserveFocus=false){
 const active=document.activeElement,focus=preserveFocus&&active?.id?active.id:null;
 const view=s.view==='projects'?projectsView():s.view==='plans'?plansView():s.view==='sources'?sourcesView():generationView();
 const retained=renderLive($('#app'),layout(view));
 if(focus&&!retained)document.getElementById(focus)?.focus({preventScroll:true});
 persist();
}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal()}
function closeModal(){$('#dialog').close()}
function accountModal(id){const p=allPlans().find(x=>x.id===id)||allPlans().find(x=>x.id===s.gen.plan)||eligiblePlans()[0];const a=account(p);const current=a.lots?.find(l=>l.id==='subscription'),extra=a.lots?.find(l=>l.id==='purchased'),bonus=a.lots?.find(l=>l.id==='bonus');const lotFields=(prefix,title,lot,initial,cost)=>`<div class="lot"><h3>${title} · valores em ${p.currency}</h3><div class="form-grid three"><label>Saldo atual<input name="${prefix}Balance" type="number" min="0" step="0.01" value="${lot?.credits??(prefix==='sub'?p.credits:0)}" required></label><label>Créditos originais do lote<input name="${prefix}Original" type="number" min="0" step="0.01" value="${lot?.originalCredits??initial}" required></label><label>Custo total original<input name="${prefix}Cost" type="number" min="0" step="0.01" value="${lot?.cost??cost}" required></label><label>Expira em (opcional)<input name="${prefix}Expiry" type="date" value="${lot?.expires??''}"></label></div></div>`;modal('Seu saldo, seu cenário',`<form id="account-form"><label>Plataforma / plano<select id="account-plan" name="plan">${planOptions('all').map(([v,l])=>`<option value="${v}" ${v===p.id?'selected':''}>${esc(l)}</option>`).join('')}</select></label><p>Informe apenas o saldo disponível neste plano. Cada plano mantém seu próprio cenário. Não consultamos sua conta externa. Datas vencidas excluem o lote do cálculo.</p><label class="inline"><input type="checkbox" name="owned" ${a.owned?'checked':''}> Já tenho acesso pago a este plano</label>${lotFields('sub','1. Assinatura · usada primeiro',current,p.credits,p.price)}${lotFields('extra','2. Créditos comprados · usados depois',extra,0,0)}${lotFields('bonus','3. Bônus informado · usado por último',bonus,0,0)}<p>Use o segundo lote para créditos comprados ou rollover com seu custo de origem. Em anual com créditos mensais, o custo do lote de assinatura deve ser o valor atribuível a um mês (${native(p.period==='annual'&&p.creditPeriod==='monthly'?p.price/12:p.price,p.currency)}), para valorar o saldo mensal corretamente. O custo do novo plano considera o pagamento anual integral.</p><div id="account-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn ghost" data-action="reset-account" data-plan="${p.id}">Usar cenário sem conta</button><button class="btn primary" type="submit">Aplicar saldo</button></div></form>`);if(!current){const el=$('[name="subCost"]');el.value=p.period==='annual'&&p.creditPeriod==='monthly'?p.price/12:p.price}}
function manualModal(){modal('Adicionar tarifa manual',`<form id="manual-form"><p>Use a tarifa exibida na sua conta. Todos os resultados serão identificados como manuais, separados dos dados verificados. Não há valores comerciais fictícios pré-preenchidos.</p><div class="form-grid"><label>Plataforma<select name="platform">${platforms.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></label><label>Nome do plano<input name="name" required maxlength="80" placeholder="Seu plano"></label><label>Modelo<select name="model">${models.map(m=>`<option value="${m.id}" ${m.id===s.gen.model?'selected':''}>${m.name}</option>`).join('')}</select></label><label>Resolução<select name="resolution">${['480p','720p','780p','1080p','4K'].map(r=>`<option ${r===s.gen.resolution?'selected':''}>${r}</option>`).join('')}</select></label><label>Moeda<select name="currency"><option>USD</option><option>BRL</option></select></label><label>Ciclo de cobrança<select name="period"><option value="monthly">Mensal</option><option value="annual">Anual</option></select></label><label>Preço integral do ciclo<input name="price" type="number" min="0" step="0.01" required></label><label>Créditos liberados agora<input name="credits" type="number" min="0.01" step="0.01" required></label><label>Liberação de créditos<select name="creditPeriod"><option value="monthly">Mensal</option><option value="annual">Anual, todos disponíveis</option></select></label><label>Regra tarifária<select name="type"><option value="presets">Clipe de duração predefinida</option><option value="second">Por segundo, com limite por clipe</option><option value="block">Por blocos, com limite por clipe</option></select></label><label>Créditos por clipe / segundo / bloco<input name="rate" type="number" min="0.000001" step="any" required></label><label>Duração fixa ou limite por clipe (s)<input name="duration" type="number" min="0.1" max="86400" step="0.1" required></label><label>Mínimo por clipe (regra por segundo/bloco)<input name="min" type="number" min="0.1" max="86400" step="0.1" value="4" required></label><label>Tamanho do bloco (s)<input name="block" type="number" min="0.1" step="0.1" value="1" required></label><label>Pacote adicional · créditos (opcional)<input name="packCredits" type="number" min="0.01" step="any"></label><label>Preço do pacote (mesma moeda)<input name="packPrice" type="number" min="0" step="0.01"></label></div><div id="manual-error" role="alert"></div><div class="dialog-actions"><button class="btn primary" type="submit">Adicionar e calcular</button></div></form>`)}
function fxModal(){modal('Conversão com origem explícita',`<form id="fx-form"><p>A taxa serve apenas para comparar moedas. O preço original de cada plataforma é preservado. Não inclui impostos, IOF ou taxas de cartão.</p><div class="form-grid"><label>Reais por 1 dólar<input type="number" name="rate" min="0.000001" max="100000" step="any" required value="${s.fx??''}"></label><label>Data da referência<input type="date" name="date" required value="${s.fxDate||today()}"></label></div><div class="dialog-actions"><button type="button" class="btn ghost" data-action="refresh-fx">Buscar referência online</button><button type="submit" class="btn primary">Aplicar taxa manual</button></div></form>`)}
async function refreshFX(){if(fxLoading)return;fxLoading=true;render();try{const res=await fetch('https://api.frankfurter.dev/v1/latest?base=USD&symbols=BRL',{signal:AbortSignal.timeout(10000)});if(!res.ok)throw new Error();const data=await res.json();numeric(data.rates?.BRL,'Câmbio',{min:0.000001});if(!/^\d{4}-\d{2}-\d{2}$/.test(data.date))throw new Error();s.fx=data.rates.BRL;s.fxDate=data.date;s.fxType='reference';s.fxFetched=today();toast('Referência cambial atualizada.');if($('#fx-form'))closeModal()}catch{toast('Referência indisponível. Você pode informar uma taxa manual.')}finally{fxLoading=false;render()}}
function exportFile(name,body,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportData(){if(s.view==='projects'){exportProject();return}const rows=rankRows(results());exportFile('framecost-geracoes.json',JSON.stringify({version:2,catalogVersion:CATALOG_VERSION,exportedAt:new Date().toISOString(),configuration:s.gen,currency:s.currency,fx:{rate:s.fx,date:s.fxDate,type:s.fxType},accounts:s.accounts,results:rows,sources},null,2),'application/json');toast('Resumo de gerações exportado.');closeModal()}
function exportProject(){const p=allPlans().find(x=>x.id===s.prj.plan),c=safe(()=>projectCalc(p));if(c.error){toast(c.error);return}const r=c.value;const data=[['FRAMECOST — ORÇAMENTO DE PRODUÇÃO'],['Projeto',s.prj.name],['Moeda do orçamento',s.currency],['Plano',info(p).name+' / '+p.name],['Preço original da assinatura',native(p.price,p.currency)],['Periodicidade',p.period],['Status do plano',sourceStatus(p)],['Data da consulta comercial',REVIEWED],['Câmbio USD/BRL',s.fx],['Data do câmbio',s.fxDate],['Origem do câmbio',s.fxType],['Cenas',r.sceneCount],['Conteúdo pretendido (s)',r.desired],['Execuções-base',r.executions],['Segmentos-base',r.segments],['Duração gerada-base (s)',r.baseGenerated],['Créditos-base',r.baseCredits],['Reserva em créditos',r.reserveCredits],['Créditos totais',r.required],...['baseAI','reserveAI','operational','total','sale','fees','profit'].map((key,i)=>[['IA cenário-base','Reserva de IA','Operação','Custo de produção','Preço sugerido','Provisão sobre a venda','Lucro estimado'][i],convert(r[key],p.currency,s.currency,s.fx)]),['Margem efetiva (%)',r.margin],['Pagamento adicional IA',r.payment==null?'A confirmar':convert(r.payment,p.currency,s.currency,s.fx)],['Custo inclui estimativa além do saldo',r.economicEstimated?'Sim':'Não'],['Observação de pagamento',r.paymentReason],['Metodologia','Custo econômico separado do pagamento adicional. Provisão genérica; sem cálculo tributário.'],['Cenas e configurações',JSON.stringify(s.prj.scenes)],['Custos operacionais',JSON.stringify(s.prj.items)],['Fontes',JSON.stringify(sources)]];exportFile('framecost-orcamento.csv','\uFEFF'+data.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Orçamento exportado em CSV.');closeModal()}
function savedModal(){modal('Projetos salvos neste navegador',s.saved.length?s.saved.map((x,i)=>`<div class="plan-fact"><div><strong>${esc(x.project.name)}</strong><span class="result-detail">Salvo em ${esc(x.date)}</span></div><div class="inline"><button class="btn ghost" data-action="load-project" data-index="${i}">Abrir</button><button class="icon-btn" data-action="delete-project" data-index="${i}" aria-label="Excluir projeto ${esc(x.project.name)}">${icon('trash')}</button></div></div>`).join(''):'<p>Nenhum projeto salvo. Use “Salvar neste navegador” na Calculadora de Projetos.</p>')}
function bindInput(e){const t=e.target;if(t.id==='account-plan'){accountModal(t.value);return}if(!t.dataset.bind)return;if(t.dataset.bind==='period'){if(e.type==='change'){changeBilling(t.value);render(true)}return}if(e.type==='input'&&t.tagName==='SELECT')return;if(e.type==='change'&&t.tagName!=='SELECT'&&t.type!=='checkbox')return;const path=t.dataset.bind.split('.');let obj=s;for(const k of path.slice(0,-1))obj=obj[k];obj[path.at(-1)]=t.type==='checkbox'?t.checked:t.hasAttribute('data-number')?(t.value===''?'':Number(t.value)):t.value;if(path.at(-1)==='model'){const parent=path.slice(0,-1).reduce((o,k)=>o[k],s);parent.resolution=resolutionForModel(allPlans().find(p=>p.id===(path[0]==='prj'?s.prj.plan:s.gen.plan)),allRules(),parent.model,parent.resolution)}if(t.dataset.bind==='gen.plan')s.gen.resolution=resolutionForModel(allPlans().find(p=>p.id===s.gen.plan),allRules(),s.gen.model,s.gen.resolution);if(t.dataset.bind==='prj.plan')for(const scene of s.prj.scenes)scene.resolution=resolutionForModel(allPlans().find(p=>p.id===s.prj.plan),allRules(),scene.model,scene.resolution);render(true)}
document.addEventListener('input',bindInput);document.addEventListener('change',bindInput);
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;if(t.tagName==='A')e.preventDefault();if(a==='nav'){s.view=t.dataset.view;render();window.scrollTo(0,0)}else if(a==='currency'){const old=s.currency,next=t.dataset.currency;if(old!==next&&s.prj.items.some(x=>Number(x.value)!==0)){if(!s.fx){toast('Informe o câmbio antes de converter seus custos operacionais.');fxModal();return}s.prj.items=s.prj.items.map(x=>({...x,value:convert(Number(x.value),old,next,s.fx)}))}s.currency=next;render()}else if(a==='focus-plan'){s.gen.plan=t.dataset.plan;s.gen.resolution=resolutionForModel(allPlans().find(p=>p.id===s.gen.plan),allRules(),s.gen.model,s.gen.resolution);render()}else if(a==='configuration'){s.gen.duration=Number(t.dataset.duration);s.gen.resolution=t.dataset.resolution;render()}else if(a==='resolution'){s.gen.resolution=t.dataset.resolution;render()}else if(a==='dismiss-audit'){s.catalogNotice=false;render()}else if(a==='model'){s.gen.model=t.dataset.model;const previous=s.gen.resolution;s.gen.resolution=resolutionForModel(allPlans().find(p=>p.id===s.gen.plan),allRules(),s.gen.model,s.gen.resolution);render();if(previous!==s.gen.resolution)toast('Resolução ajustada para '+s.gen.resolution+' neste plano.');}else if(a==='duration'){s.gen.duration=Number(t.dataset.duration);render()}else if(a==='details'){s.expanded=s.expanded===t.dataset.plan?null:t.dataset.plan;render()}else if(a==='retry-up'||a==='retry-down'){s.gen.count=Math.max(1,Math.min(100000,Number(s.gen.count)+(a==='retry-up'?1:-1)));render()}else if(a==='account')accountModal(t.dataset.plan||s.gen.plan);else if(a==='manual')manualModal();else if(a==='fx')fxModal();else if(a==='refresh-fx')refreshFX();else if(a==='close')closeModal();else if(a==='reset-account'){delete s.accounts[t.dataset.plan];closeModal();render();toast('Cenário de nova contratação aplicado.')}else if(a==='use-project'){s.prj.scenes[0]={...s.prj.scenes[0],duration:s.gen.duration,model:s.gen.model,resolution:s.gen.resolution,attempts:s.gen.count};const r=selectedResult(rankRows(results()));if(r)s.prj.plan=r.p.id;s.view='projects';render();window.scrollTo(0,0)}else if(a==='add-scene'){s.prj.scenes.push({...s.prj.scenes.at(-1),id:crypto.randomUUID(),name:'Novo grupo de cenas',quantity:1});render()}else if(a==='remove-scene'){if(s.prj.scenes.length===1){toast('Mantenha pelo menos um grupo de cenas.');return}s.prj.scenes.splice(Number(t.dataset.index),1);render()}else if(a==='add-cost'){s.prj.items.push({id:crypto.randomUUID(),name:'Novo custo',type:'fixed',value:0,hours:1});render()}else if(a==='remove-cost'){s.prj.items.splice(Number(t.dataset.index),1);render()}else if(a==='save-project'){s.saved.unshift({date:today(),currency:s.currency,project:structuredClone(s.prj)});s.saved=s.saved.slice(0,50);persist();toast('Projeto salvo neste navegador.')}else if(a==='saved')savedModal();else if(a==='load-project'){const x=s.saved[Number(t.dataset.index)];s.prj=structuredClone(x.project);s.currency=x.currency;const savedPlan=allPlans().find(p=>p.id===s.prj.plan);if(savedPlan)s.period=savedPlan.period;s.view='projects';closeModal();render();toast('Projeto carregado.')}else if(a==='delete-project'){s.saved.splice(Number(t.dataset.index),1);persist();savedModal()}else if(a==='delete-manual'){s.manual=s.manual.filter(x=>x.plan.id!==t.dataset.plan);render();toast('Tarifa manual removida.')}else if(a==='export'){modal('Leve seus números com você',`<p>${s.view==='projects'?'Exporte o orçamento com custos, reserva, margem, fontes e preço de venda.':'O resumo contém configurações, consumo, custo econômico, contratação e fontes de cada alternativa.'}</p><div class="dialog-actions"><button class="btn primary" data-action="${s.view==='projects'?'export-project':'export-json'}">${icon('download')} ${s.view==='projects'?'Baixar CSV do orçamento':'Baixar resumo JSON'}</button><button class="btn ghost" data-action="print">Imprimir / PDF</button></div>`)}else if(a==='export-json')exportData();else if(a==='export-project')exportProject();else if(a==='print'){closeModal();window.print()}});
document.addEventListener('submit',e=>{if(!['account-form','manual-form','fx-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target),v=k=>f.get(k);try{if(e.target.id==='fx-form'){s.fx=numeric(v('rate'),'Taxa',{min:.000001,max:100000});s.fxDate=v('date');s.fxType='manual';s.fxFetched=today();closeModal();render();toast('Taxa manual aplicada.')}else if(e.target.id==='account-form'){const p=allPlans().find(x=>x.id===v('plan'));const lots=[];for(const [prefix,id,priority]of[['sub','subscription',0],['extra','purchased',2],['bonus','bonus',3]]){const credits=numeric(v(prefix+'Balance'),'Saldo'),originalCredits=numeric(v(prefix+'Original'),'Créditos originais'),cost=numeric(v(prefix+'Cost'),'Custo do lote');if(credits>originalCredits)throw new Error('O saldo atual não pode exceder os créditos originais do lote.');if(credits>0&&originalCredits<=0)throw new Error('Informe os créditos originais do lote.');if(originalCredits>0)lots.push({id,priority,credits,originalCredits,cost,expires:v(prefix+'Expiry')||null})}s.accounts[p.id]={owned:v('owned')==='on',lots};closeModal();render();toast('Saldo informado aplicado a este plano.')}else {const id='manual-'+crypto.randomUUID(),period=v('period'),creditPeriod=v('creditPeriod');if(period==='monthly'&&creditPeriod==='annual')throw new Error('Liberação anual exige um ciclo anual nesta versão.');const type=v('type'),duration=numeric(v('duration'),'Duração',{min:.1,max:86400}),min=type==='presets'?duration:numeric(v('min'),'Mínimo',{min:.1,max:duration}),rate=numeric(v('rate'),'Tarifa',{min:.000001});const pc=v('packCredits'),pp=v('packPrice');if(Boolean(pc)!==Boolean(pp)&&!(pc&&pp==='0'))throw new Error('Informe créditos e preço do pacote juntos.');const plan={id,platform:v('platform'),name:v('name'),price:numeric(v('price'),'Preço'),credits:numeric(v('credits'),'Créditos',{min:.01}),currency:v('currency'),period,creditPeriod,source:'manual',status:'manual',expires:'Conforme sua conta; informe validade no saldo',limits:'Dados manuais informados em '+today(),topup:pc?{credits:numeric(pc,'Créditos do pacote',{min:.01}),price:numeric(pp,'Preço do pacote')}:null};const rule={id,planId:id,platform:plan.platform,model:v('model'),resolution:v('resolution'),status:'manual',source:'manual',quality:'Manual',mode:'Texto / imagem',audio:'Conforme valor informado',note:'Tarifa manual, não verificada automaticamente.',billing:type==='presets'?{type,options:[{seconds:duration,credits:rate}]}:{type,min,max:duration,step:1,rate,block:numeric(v('block'),'Bloco',{min:.1})}};s.manual.push({plan,rule});s.period=plan.period;s.gen.plan=plan.id;s.gen.model=rule.model;s.gen.resolution=rule.resolution;closeModal();render();toast('Tarifa manual adicionada.')}}catch(err){const target=$('#account-error')||$('#manual-error');if(target)target.innerHTML=`<div class="error">${esc(err.message)}</div>`;else toast(err.message)}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
s.gen.resolution=resolutionForModel(allPlans().find(p=>p.id===s.gen.plan),allRules(),s.gen.model,s.gen.resolution);
render();
if(!s.fx)refreshFX();

function resolutionAudit(p){
  if(!p)return '';
  const resolutions=[...new Set(allRules().filter(r=>r.platform===p.platform&&r.model===s.gen.model).map(r=>r.resolution))].sort((a,b)=>parseInt(a)-parseInt(b));
  return `<section class="card resolution-audit" aria-label="Resoluções no mesmo plano"><div class="section-title"><h2>Resoluções no mesmo plano</h2></div><p>${esc(info(p).name)} · ${esc(p.name)} · ${p.period==='annual'?'anual':'mensal'} · ${s.gen.duration}s por execução. Compare cada resolução sem trocar a plataforma.</p><div class="resolution-grid">${resolutions.map(resolution=>{
    const config={...s.gen,resolution};
    const r=matchingRule(p,allRules(),config),c=safe(()=>{
      if(!r||!r.billing||r.status==='pending'||(r.status==='estimated'&&!s.includeEstimated))throw new Error('Tarifa pendente');
      return simulate(p,r,s.gen.duration,1,account(p));
    });
    return `<button class="resolution-option ${s.gen.resolution===resolution?'active':''}" data-action="resolution" data-resolution="${esc(resolution)}" aria-pressed="${s.gen.resolution===resolution}"><strong>${esc(resolution)}</strong><span>${c.value?economicMoney(c.value,p.currency):'A confirmar'}</span><small>${c.value?fmt(c.value.required,2)+' cr. · '+fmt(c.value.generated,1)+'s gerados':esc(c.error)}</small></button>`;
  }).join('')||'<p>Sem resolução tarifada nesta plataforma.</p>'}</div></section>`;
}
function changeBilling(period){
  if(!['monthly','annual'].includes(period))return;
  for(const [object,key] of [[s.gen,'plan'],[s.prj,'plan']]){
    const equivalent=correspondingPlan(allPlans(),object[key],period);
    if(equivalent)object[key]=equivalent.id;
  }
  s.period=period;s.expanded=null;
}

function durationOptions(p){
 const values=new Set([4,5,6,8,10,15,20,30,45,60]);
 if(['wan-3','wan-prime'].includes(s.gen.model))values.add(2);
 for(const choice of configurationChoices(p,allRules(),s.gen))if(choice.duration<=60)values.add(choice.duration);
 return [...values].sort((a,b)=>a-b);
}
function configurationHint(p,pending){
 const r=p&&matchingRule(p,allRules(),s.gen),quote=r?.billing?.type==='reference';
 if(!pending&&!quote)return '';
 const choices=configurationChoices(p,allRules(),s.gen).filter(c=>c.duration!==Number(s.gen.duration)||c.resolution!==s.gen.resolution);
 return '<div class="audit-notice configuration-help" role="status"><strong>'+ (pending?'Esta configuração precisa de outra tarifa.':'Cotações publicadas para este plano.')+'</strong><p>'+esc(pending?.reason||'Estas durações têm preço confirmado. Outras durações exigem uma tarifa própria.')+'</p>'+ (choices.length?'<p>Calcular uma configuração confirmada no mesmo plano:</p><div class="configuration-actions">'+choices.map(c=>'<button class="btn ghost" data-action="configuration" data-duration="'+c.duration+'" data-resolution="'+esc(c.resolution)+'">Calcular '+c.duration+'s em '+esc(c.resolution)+'</button>').join('')+'</div>':'')+'<p>O plano permanece selecionado. Você também pode informar a tarifa exibida na sua conta.</p><button class="btn ghost" data-action="manual">Informar tarifa desta configuração</button></div>';
}
